package com.example.book_management_api.service;

import com.example.book_management_api.dto.BookDto;
import com.example.book_management_api.entity.Book;
import com.example.book_management_api.repository.BookRepository;
import jakarta.validation.Valid;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import javax.persistence.EntityNotFoundException;
import java.util.List;
import java.util.Optional;

/**
 * Core service handling {@link Book} persistence.
 */
@Service
public class BookService {

    private final BookRepository bookRepository;

    public BookService(BookRepository bookRepository) {
        this.bookRepository = bookRepository;
    }

    /**
     * Persists a new {@link Book} created from a {@link BookDto}.
     *
     * @param bookDto data transfer object containing book details
     * @return the persisted {@link Book}
     */
    @Transactional
    public Book create(@Valid BookDto bookDto) {
        Book book = Book.builder()
                .title(bookDto.getTitle())
                .author(bookDto.getAuthor())
                .isbn(bookDto.getIsbn())
                .publishedDate(bookDto.getPublishedDate())
                .build();
        return create(book);
    }

    /**
     * Persists a new {@link Book}.
     *
     * @param book entity to persist
     * @return persisted entity
     */
    @Transactional
    public Book create(Book book) {
        return bookRepository.save(book);
    }

    /**
     * Retrieves a {@link Book} by its identifier.
     *
     * @param id primary key
     * @return the found {@link Book}
     * @throws EntityNotFoundException if no book with the given id exists
     */
    @Transactional(readOnly = true)
    public Book getById(Long id) {
        return bookRepository.findById(id)
                .orElseThrow(() -> new EntityNotFoundException("Book not found with id " + id));
    }

    /**
     * Retrieves a {@link Book} by its identifier, returning an {@link Optional}.
     *
     * @param id primary key
     * @return optional containing the book if found
     */
    @Transactional(readOnly = true)
    public Optional<Book> findById(Long id) {
        return bookRepository.findById(id);
    }

    /**
     * Returns all books.
     *
     * @return list of books
     */
    @Transactional(readOnly = true)
    public List<Book> getAll() {
        return bookRepository.findAll();
    }

